// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/settings/DevicesShot.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Settings → Devices, ported from the app's DevicesMenu and DeviceInfo
 * (src/panels/DevicesMenu.tsx, DeviceInfo.tsx): the connected devices with
 * Devbox expanded to its system details and the tmux sessions found on it,
 * then the form that adds a device.
 */
import { ChevronDown, ChevronRight, Plus, RefreshCw, ServerCog, SquareTerminal, Trash2 } from "lucide-react";
import { AgentMark, type Agent } from "../../home/AppUI";
import { DeviceIcon } from "./DeviceIcon";
import { SettingsWindow } from "./SettingsWindow";

interface ManagedDevice {
  name: string;
  user?: string;
  host: string;
  os: "mac" | "linux";
  local: boolean;
}

const DEVICES: ManagedDevice[] = [
  { name: "This Device", host: "localhost", os: "mac", local: true },
  { name: "Devbox", user: "dev", host: "devbox", os: "linux", local: false },
];

/** Devbox's tmux sessions as a scan lists them: age, then live (attached) and open (a tile). */
const SESSIONS: { name: string; agent: Agent; launcher: string; age: string; live: boolean; open: boolean; workspace?: string }[] = [
  { name: "api-tests", agent: "claude", launcher: "Claude Code", age: "3h", live: true, open: true, workspace: "fieldnotes" },
  { name: "migrations", agent: "codex", launcher: "Codex", age: "1d", live: false, open: false },
  { name: "logs", agent: "terminal", launcher: "zsh", age: "2d", live: false, open: false },
];

/** The app's Switch, small (src/ui/Switch.tsx). */
function Switch({ on, title }: { on: boolean; title: string }) {
  return (
    <button type="button" className={`switch ${on ? "switch-on" : ""} switch-sm`} role="switch" aria-checked={on} title={title} aria-label={title}>
      <span className="switch-knob" />
    </button>
  );
}

/** The app's Select trigger (src/ui/Select.tsx), closed. */
function SelectTrigger({ label }: { label: string }) {
  return (
    <button type="button" className="cselect" aria-haspopup="listbox" aria-expanded={false}>
      <span className="cselect-value">{label}</span>
      <ChevronDown size={14} className="muted-icon" />
    </button>
  );
}

/** DeviceInfo for Devbox, details folded (More details). */
function DevboxInfo() {
  // 41.2 GiB of 62.7 GiB available: 34% in use.
  const usedRatio = 34;
  return (
    <section className="device-info" aria-label="Devbox device details" aria-busy={false}>
      <div className="device-info-heading">
        <span className="device-info-os">
          <DeviceIcon os="linux" size={21} />
          <span>
            <strong>Ubuntu</strong>
            <span>24.04.1 LTS</span>
          </span>
        </span>
        <button type="button" className="usage-refresh async-button" title="Refresh device details" aria-label="Refresh device details" aria-busy={false}>
          <span className="async-button-icon" style={{ width: 14, height: 14 }} aria-hidden="true">
            <RefreshCw size={14} strokeWidth={2} />
          </span>
        </button>
      </div>
      <div className="device-info-health" role="status">
        <span className="device-info-status device-info-reachable">Reachable</span>
      </div>
      <dl className="device-info-grid">
        <div className="device-info-item">
          <dt>Uptime</dt>
          <dd>12d 4h 31m</dd>
        </div>
        <div className="device-info-item">
          <dt>CPU</dt>
          <dd>16 logical cores</dd>
        </div>
        <div className="device-info-item device-info-wide">
          <dt>Memory</dt>
          <dd>
            41.2 GiB available / 62.7 GiB total
            <span className="device-info-memory" role="meter" aria-label="Memory in use" aria-valuemin={0} aria-valuemax={100} aria-valuenow={usedRatio}>
              <span style={{ width: `${usedRatio}%` }} />
            </span>
          </dd>
        </div>
      </dl>
      <button type="button" className="btn btn-sm device-info-more" aria-expanded={false}>
        More details
      </button>
    </section>
  );
}

function DevicesPage() {
  return (
    <div className="settings-page device-info-panel">
      <section className="settings-section device-list">
        <h3>Connected devices</h3>
        {DEVICES.map((d) => {
          const expanded = !d.local;
          return (
            <div key={d.name} className={`managed-device ${expanded ? "expanded" : ""}`}>
              <div className="managed-device-header">
                <button type="button" className="managed-device-toggle" aria-expanded={expanded}>
                  {expanded ? <ChevronDown size={14} className="muted-icon" /> : <ChevronRight size={14} className="muted-icon" />}
                  <DeviceIcon os={d.os} size={15} />
                  <span className="device-main">
                    <span className="device-name">
                      {d.name}
                      {d.local ? <span className="device-tag">current</span> : null}
                    </span>
                    <span className="device-sub">
                      {d.user ? `${d.user}@` : ""}
                      {d.host}
                    </span>
                  </span>
                  <span className="managed-device-kind">{d.local ? "Local" : "SSH"}</span>
                </button>
                {!d.local ? <Switch on title={`Disable ${d.name}`} /> : null}
                {!d.local ? (
                  <button className="icon-btn icon-btn-danger" title="Remove device" aria-label={`Remove ${d.name}`}>
                    <Trash2 size={14} />
                  </button>
                ) : null}
              </div>
              {expanded ? (
                <div className="managed-device-details">
                  <DevboxInfo />
                  <div className="device-scan-head">
                    <span className="device-scan-title">
                      Sessions
                      <span className="field-hint">{SESSIONS.length}</span>
                    </span>
                    <button type="button" className="icon-btn" title="Re-scan" aria-label="Re-scan" aria-busy={false}>
                      <span className="icon-inner">
                        <RefreshCw size={12} strokeWidth={1.9} />
                      </span>
                    </button>
                  </div>
                  {SESSIONS.map((sess) => (
                    <div className="managed-session" key={sess.name}>
                      <span className="scan-icon">
                        <span title={`Launcher: ${sess.launcher}. Effective model unavailable.`} style={{ display: "inline-flex" }}>
                          {sess.agent === "terminal" ? <SquareTerminal size={13} /> : <AgentMark agent={sess.agent} size={13} tinted />}
                        </span>
                      </span>
                      <span className="scan-main">
                        <span className="scan-name">{sess.name}</span>
                        <span className="scan-meta">
                          <span>{sess.age}</span>
                          {sess.live ? " · live" : ""}
                          {sess.open ? " · open" : ""}
                        </span>
                      </span>
                      <div className="scan-ws">
                        <SelectTrigger label={sess.workspace ?? "Add to workspace..."} />
                      </div>
                      <button className="icon-btn icon-btn-danger" title="Terminate">
                        <Trash2 size={13} />
                      </button>
                    </div>
                  ))}
                </div>
              ) : null}
            </div>
          );
        })}
      </section>

      <section className="settings-section device-add">
        <h3>Add a device</h3>
        <div className="settings-form">
          <label className="settings-field">
            <span className="field-label">Name</span>
            <input className="field-input" placeholder="My server" readOnly />
          </label>
          <label className="settings-field">
            <span className="field-label">Host / IP</span>
            <input className="field-input" placeholder="SSH alias or IP address" readOnly />
          </label>
          <label className="settings-field">
            <span className="field-label">SSH user</span>
            <input className="field-input" placeholder="Optional" readOnly />
          </label>
        </div>
        <div className="settings-actions">
          <button className="btn btn-accent btn-sm" disabled>
            <Plus size={14} strokeWidth={2.2} />
            Add device
          </button>
          <button className="btn btn-sm">
            <ServerCog size={14} strokeWidth={2} />
            Install agent over SSH
          </button>
        </div>
      </section>
    </div>
  );
}

export function DevicesShot() {
  return (
    <SettingsWindow section="devices" backdrop="devices">
      <DevicesPage />
    </SettingsWindow>
  );
}
